protected void rpt_ItemDataBound(object sender, RepeaterItemEventArgs e)
{
    if (e.Item.ItemType != ListItemType.Item && e.Item.ItemType != ListItemType.AlternatingItem)
        return;

    int registerId = Convert.ToInt32(DataBinder.Eval(e.Item.DataItem, "TiemChungRegisterID"));
    CheckBox chkSelect = e.Item.FindControl("chkSelect") as CheckBox;
    if (chkSelect != null)
        chkSelect.Checked = SelectedRegisterIds.Contains(registerId);
}

private void SaveCurrentPageSelections()
{
    if (rpt.Items == null || rpt.Items.Count == 0)
        return;

    List<int> selectedIds = SelectedRegisterIds;
    foreach (RepeaterItem item in rpt.Items)
    {
        if (item.ItemType != ListItemType.Item && item.ItemType != ListItemType.AlternatingItem)
            continue;

        HiddenField hidRegisterId = item.FindControl("hidRegisterId") as HiddenField;
        CheckBox chkSelect = item.FindControl("chkSelect") as CheckBox;
        if (hidRegisterId == null || chkSelect == null)
            continue;

        int registerId;
        if (!int.TryParse(hidRegisterId.Value, out registerId))
            continue;

        if (chkSelect.Checked)
        {
            if (!selectedIds.Contains(registerId))
                selectedIds.Add(registerId);
        }
        else
        {
            selectedIds.Remove(registerId);
        }
    }

    SelectedRegisterIds = selectedIds;
}

private List<int> GetSelectedRegisterIdsForExport()
{
    SaveCurrentPageSelections();
    return new List<int>(SelectedRegisterIds);
}

private DataTable BuildExportTable(List<int> selectedIds)
{
    DataTable dtExport = new DataTable();
    dtExport.Columns.Add("TiemChungRegisterID", typeof(int));
    dtExport.Columns.Add("FullName", typeof(string));
    dtExport.Columns.Add("Phone", typeof(string));
    dtExport.Columns.Add("Email", typeof(string));
    dtExport.Columns.Add("Content", typeof(string));
    dtExport.Columns.Add("StatusText", typeof(string));
    dtExport.Columns.Add("ClientIP", typeof(string));
    dtExport.Columns.Add("CreatedDate", typeof(string));

    foreach (int registerId in selectedIds)
    {
        INFO_TiemChungRegister objRegister = new INFO_TiemChungRegister(registerId);
        if (objRegister.TiemChungRegisterID == null || objRegister.TiemChungRegisterID.Value <= 0)
            continue;

        DataRow row = dtExport.NewRow();
        row["TiemChungRegisterID"] = objRegister.TiemChungRegisterID.Value;
        row["FullName"] = objRegister.FullName ?? string.Empty;
        row["Phone"] = objRegister.Phone ?? string.Empty;
        row["Email"] = objRegister.Email ?? string.Empty;
        row["Content"] = objRegister.Content ?? string.Empty;
        row["StatusText"] = GetStatusText(objRegister.Status);
        row["ClientIP"] = objRegister.ClientIP ?? string.Empty;
        row["CreatedDate"] = objRegister.CreatedDate.HasValue
            ? objRegister.CreatedDate.Value.ToString("dd/MM/yyyy HH:mm", CultureInfo.InvariantCulture)
            : string.Empty;
        dtExport.Rows.Add(row);
    }

    return dtExport;
}

private string GetStatusText(byte? statusValue)
{
    if (statusValue.HasValue && statusValue.Value == StatusProcessed)
        return "Đã xử lý";
    return "Mới";
}

private string EscapeCsvValue(object value)
{
    if (value == null || value == DBNull.Value)
        return string.Empty;

    string text = Convert.ToString(value);
    if (text.IndexOf('"') >= 0)
        text = text.Replace("\"", "\"\"");
    if (text.IndexOf(';') >= 0 || text.IndexOf('\n') >= 0 || text.IndexOf('\r') >= 0)
        text = "\"" + text + "\"";
    return text;
}

private void ExportCsv(DataTable dtExport)
{
    string fileName = string.Format("DangKy-TiemChung-{0}.csv", DateTime.Now.ToString("yyyyMMddHHmmss"));
    Response.Clear();
    Response.Buffer = true;
    Response.ContentType = "text/csv";
    Response.ContentEncoding = Encoding.UTF8;
    Response.Charset = "UTF-8";
    Response.AddHeader("Content-Disposition", "attachment;filename=" + fileName);

    StringBuilder sb = new StringBuilder();
    sb.AppendLine("ID;Họ tên;Điện thoại;Email;Nội dung;Trạng thái;IP;Ngày đăng ký");
    foreach (DataRow row in dtExport.Rows)
    {
        sb.Append(EscapeCsvValue(row["TiemChungRegisterID"]));
        sb.Append(";");
        sb.Append(EscapeCsvValue(row["FullName"]));
        sb.Append(";");
        sb.Append(EscapeCsvValue(row["Phone"]));
        sb.Append(";");
        sb.Append(EscapeCsvValue(row["Email"]));
        sb.Append(";");
        sb.Append(EscapeCsvValue(row["Content"]));
        sb.Append(";");
        sb.Append(EscapeCsvValue(row["StatusText"]));
        sb.Append(";");
        sb.Append(EscapeCsvValue(row["ClientIP"]));
        sb.Append(";");
        sb.AppendLine(EscapeCsvValue(row["CreatedDate"]));
    }

    Response.Write("\uFEFF");
    Response.Write(sb.ToString());
    Response.End();
}

private void ExportExcel(DataTable dtExport)
{
    string fileName = string.Format("DangKy-TiemChung-{0}.xls", DateTime.Now.ToString("yyyyMMddHHmmss"));
    Response.Clear();
    Response.Buffer = true;
    Response.ContentType = "application/vnd.ms-excel";
    Response.ContentEncoding = Encoding.UTF8;
    Response.Charset = "UTF-8";
    Response.AddHeader("Content-Disposition", "attachment;filename=" + fileName);

    StringBuilder sb = new StringBuilder();
    sb.Append("<html><head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" /></head><body>");
    sb.Append("<table border='1' cellspacing='0' cellpadding='4'>");
    sb.Append("<tr>");
    sb.Append("<th>ID</th><th>Họ tên</th><th>Điện thoại</th><th>Email</th>");
    sb.Append("<th>Nội dung</th><th>Trạng thái</th><th>IP</th><th>Ngày đăng ký</th>");
    sb.Append("</tr>");

    foreach (DataRow row in dtExport.Rows)
    {
        sb.Append("<tr>");
        sb.Append("<td>").Append(System.Web.HttpUtility.HtmlEncode(Convert.ToString(row["TiemChungRegisterID"]))).Append("</td>");
        sb.Append("<td>").Append(System.Web.HttpUtility.HtmlEncode(Convert.ToString(row["FullName"]))).Append("</td>");
        sb.Append("<td>").Append(System.Web.HttpUtility.HtmlEncode(Convert.ToString(row["Phone"]))).Append("</td>");
        sb.Append("<td>").Append(System.Web.HttpUtility.HtmlEncode(Convert.ToString(row["Email"]))).Append("</td>");
        sb.Append("<td>").Append(System.Web.HttpUtility.HtmlEncode(Convert.ToString(row["Content"]))).Append("</td>");
        sb.Append("<td>").Append(System.Web.HttpUtility.HtmlEncode(Convert.ToString(row["StatusText"]))).Append("</td>");
        sb.Append("<td>").Append(System.Web.HttpUtility.HtmlEncode(Convert.ToString(row["ClientIP"]))).Append("</td>");
        sb.Append("<td>").Append(System.Web.HttpUtility.HtmlEncode(Convert.ToString(row["CreatedDate"]))).Append("</td>");
        sb.Append("</tr>");
    }

    sb.Append("</table></body></html>");
    Response.Write(sb.ToString());
    Response.End();
}

protected void btnExportCsv_Click(object sender, EventArgs e)
{
    List<int> selectedIds = GetSelectedRegisterIdsForExport();
    if (selectedIds.Count == 0)
    {
        ShowMessage("Vui lòng chọn ít nhất một đăng ký để xuất.", false);
        return;
    }

    DataTable dtExport = BuildExportTable(selectedIds);
    if (dtExport.Rows.Count == 0)
    {
        ShowMessage("Không có dữ liệu để xuất.", false);
        return;
    }

    ExportCsv(dtExport);
}

protected void btnExportExcel_Click(object sender, EventArgs e)
{
    List<int> selectedIds = GetSelectedRegisterIdsForExport();
    if (selectedIds.Count == 0)
    {
        ShowMessage("Vui lòng chọn ít nhất một đăng ký để xuất.", false);
        return;
    }

    DataTable dtExport = BuildExportTable(selectedIds);
    if (dtExport.Rows.Count == 0)
    {
        ShowMessage("Không có dữ liệu để xuất.", false);
        return;
    }

    ExportExcel(dtExport);
}

